function guide(){legacy.guide();let html=$('#app').innerHTML;html=html.replace('再次答对会标记“已掌握”，但历史错题保留，可再次练习。','错题至少隔20小时的两次答对后自动标记掌握；复习间隔按1、3、7、14、30天安排，历史错题始终保留。').replace('内容核对日期：2026-10-26','内容核对日期：2026-10-27').replace('20分钟与90分钟练习卷、抽题数量及等权评分均为本站训练设计。','20题快速检测、60题综合卷、200题节奏训练与自定义组卷，均为本站原创题组卷，按每题等权评分。');$('#app').innerHTML=html+`<section class="card" style="margin-top:22px"><h2>本次联网核对与内容边界</h2><p>内置 ${builtInCount} 题，其中60题属于六类公式的计算变式，其余为概念或情境题。所有题目均为原创学习材料，不是官方真题，也不按数量声称穷尽考点。难度标签用于学习编排，不是统计测量结果。</p><p>公开简章中存在200题/90分钟的安排，本项目据此提供节奏训练；不同机构的题型、分值和技能平台仍需核对。交互实操为本地教学沙盒：SQL仅实现页面列明的子集，不执行任意Python或连接外部数据库。</p>${referenceSources.map(s=>`<div class="module"><a href="${s.url}" target="_blank" rel="noopener">${esc(s.name)} ↗</a><p class="muted">${esc(s.use)}</p></div>`).join('')}</section><section class="card" style="margin-top:22px"><h2>功能使用地图</h2><table><tr><th>目标</th><th>入口与操作</th></tr><tr><td>新手入门</td><td>速记卡翻面理解 → 对应题 → 自己写错因</td></tr><tr><td>提高练习效率</td><td>智能训练优先到期错题、薄弱模块和未做题</td></tr><tr><td>增加个人资料</td><td>题库管理下载JSON模板 → 导入校验 → 预览确认</td></tr><tr><td>强化技能</td><td>交互实操提交操作获得客观检查；实操训练完成书面案例自查</td></tr><tr><td>评估进展</td><td>学习分析查看覆盖率、近期正确率、错因与考试趋势</td></tr><tr><td>迁移设备</td><td>导出完整学习备份 → 新设备导入（包含自有题库）</td></tr></table></section>`}
function casesPage(){legacy.casesPage();$('#app').insertAdjacentHTML('afterbegin','<section class="note" style="margin-bottom:20px">这里保留5个书面方案案例，作答自动保存、自查清单由你手动勾选。需要客观判分的操作任务，请进入 <a href="#lab">交互实操 →</a></section>')}
function backup(){downloadFile(`训练师学习备份-${today()}.json`,JSON.stringify({...state,version:2},null,2));toast('已导出：学习记录、实操作答及自有题库')}
function validateBackup(d){if(!safeObject(d)||![1,2].includes(d.version))throw Error('不支持的备份版本');const arrs=['history','stars','learned','days','exams','plan'];if(arrs.some(k=>!Array.isArray(d[k])))throw Error('备份缺少记录数组');const objs=['wrong','notes','caseAnswers','caseChecks'];if(objs.some(k=>!safeObject(d[k])))throw Error('备份缺少必要字段');let custom=d.custom||[];if(!Array.isArray(custom)||custom.length>10000||!custom.every(q=>validQuestion(q)&&q.id.startsWith('custom-')))throw Error('自有题库损坏');if(new Set(custom.map(q=>q.id)).size!==custom.length)throw Error('题号重复');let all=[...questions.filter(q=>!q.id.startsWith('custom-')),...custom],map=new Map(all.map(q=>[q.id,q]));let answers=(id,a)=>map.has(id)&&Array.isArray(a)&&new Set(a).size===a.length&&a.every(i=>Number.isInteger(i)&&i>=0&&i<map.get(id).options.length);if(!d.history.every(h=>safeObject(h)&&map.has(h.id)&&typeof h.ok==='boolean'&&Number.isFinite(h.at)&&(!h.answer||answers(h.id,h.answer))))throw Error('作答记录无效');if(!d.stars.every(id=>map.has(id))||!d.learned.every(i=>Number.isInteger(i)&&i>=0&&i<facts.length)||!d.days.every(s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s))||!d.plan.every(i=>Number.isInteger(i)&&i>=0&&i<14))throw Error('学习进度无效');if(typeof d.date!=='string'||(d.date&&!/^\d{4}-\d{2}-\d{2}$/.test(d.date)))throw Error('日期无效');if(!Object.entries(d.wrong).every(([id,w])=>map.has(id)&&safeObject(w)&&Number.isInteger(w.count)&&w.count>=0&&typeof w.mastered==='boolean'))throw Error('错题记录无效');if(!Object.values(d.notes).every(v=>typeof v==='string')||!Object.values(d.caseAnswers).every(v=>typeof v==='string')||!Object.values(d.caseChecks).every(v=>Array.isArray(v)&&v.every(Number.isInteger)))throw Error('笔记格式无效');let checkSession=s=>{if(!safeObject(s)||!Array.isArray(s.ids)||!s.ids.length||new Set(s.ids).size!==s.ids.length||!s.ids.every(id=>map.has(id))||!safeObject(s.answers)||!Object.entries(s.answers).every(([id,a])=>s.ids.includes(id)&&answers(id,a)))return false;if(s.pos!==undefined&&(!Number.isInteger(s.pos)||s.pos<0||s.pos>=s.ids.length))return false;if(s.orders&&!Object.entries(s.orders).every(([id,order])=>map.has(id)&&answers(id,order)&&order.length===map.get(id).options.length))return false;if(s.flags&&(!Array.isArray(s.flags)||!s.flags.every(id=>s.ids.includes(id))))return false;return true};if(!d.exams.every(e=>checkSession(e)&&Number.isFinite(e.at)&&Number.isFinite(e.score)&&e.score>=0&&e.score<=100&&Number.isFinite(e.right)))throw Error('考试记录无效');if(d.activeExam&&(!checkSession(d.activeExam)||!Number.isFinite(d.activeExam.end)||!Number.isFinite(d.activeExam.started)||d.activeExam.exam!==true))throw Error('续考数据无效');if(d.activePractice&&(!checkSession(d.activePractice)||!safeObject(d.activePractice.submitted)||!Object.entries(d.activePractice.submitted).every(([id,v])=>d.activePractice.ids.includes(id)&&v===true)))throw Error('续练数据无效');if(d.reviews&&(!safeObject(d.reviews)||!Object.entries(d.reviews).every(([id,r])=>map.has(id)&&safeObject(r)&&Number.isFinite(r.due)&&Number.isInteger(r.streak)&&r.streak>=0)))throw Error('复习计划无效');if(d.causes&&(!safeObject(d.causes)||!Object.values(d.causes).every(v=>typeof v==='string')))throw Error('错因格式无效');if(d.labs){if(!safeObject(d.labs)||!Object.entries(d.labs).every(([id,v])=>Object.hasOwn(labNames,id)&&safeObject(v)&&Number.isFinite(v.score)&&v.score>=0&&v.score<=100&&Number.isFinite(v.at)))throw Error('实操记录无效');if(d.labs.metrics?.answers&&(!Array.isArray(d.labs.metrics.answers)||d.labs.metrics.answers.length!==3))throw Error('指标练习记录无效');if(d.labs.flow?.order&&(!Array.isArray(d.labs.flow.order)||d.labs.flow.order.length!==8||new Set(d.labs.flow.order).size!==8||!d.labs.flow.order.every(i=>Number.isInteger(i)&&i>=0&&i<8)))throw Error('流程顺序无效');if(d.labs.sql?.query&&typeof d.labs.sql.query!=='string')throw Error('查询记录无效')}return true}
function validBackup(d){try{return validateBackup(d)}catch{return false}}
async function restore(ev){let f=ev.target.files[0];if(!f)return;try{if(f.size>20e6)throw Error('备份超过20MB');let d=JSON.parse(await f.text());validateBackup(d);if(!confirm('导入会替换当前学习记录与自有题库。建议先导出当前备份。确认导入？'))return;questions.splice(0,questions.length,...questions.filter(q=>!q.id.startsWith('custom-')),...(d.custom||[]));state={...fresh(),...d,version:2,custom:d.custom||[],reviews:d.reviews||{},causes:d.causes||{},labs:d.labs||{},settings:{daily:[10,20,30,50].includes(d.settings?.daily)?d.settings.daily:20},activePractice:d.activePractice||null};for(let [id,w] of Object.entries(state.wrong))if(!state.reviews[id])state.reviews[id]={streak:w.mastered?2:0,due:Date.now(),last:0};cleanConfig={dedupe:false,trim:false,invalid:false,missing:'keep',...state.labs.clean?.config};labelDraft=state.labs.label?.answers||{};flowOrder=state.labs.flow?.order||[3,0,7,1,5,2,6,4];sqlDraft=state.labs.sql?.query||'SELECT id, text FROM samples WHERE label IS NULL;';metricDraft=state.labs.metrics?.answers||['','',''];session=null;result=null;save();render();toast('备份已恢复，包括自有题库与实操记录')}catch(e){toast('导入失败：'+e.message)}finally{ev.target.value=''}}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
window.addEventListener('beforeunload',()=>{if(session&&!session.exam)persistSession()});
render();
